25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * Ethernet multiplexer
33	 */
34	module eth_mux #
35	(
36	    parameter S_COUNT = 4,
37	    parameter DATA_WIDTH = 8,
38	    parameter KEEP_ENABLE = (DATA_WIDTH>8),
39	    parameter KEEP_WIDTH = (DATA_WIDTH/8),
40	    parameter ID_ENABLE = 0,
41	    parameter ID_WIDTH = 8,
42	    parameter DEST_ENABLE = 0,
43	    parameter DEST_WIDTH = 8,
44	    parameter USER_ENABLE = 1,
45	    parameter USER_WIDTH = 1
46	)
47	(
48	    input  wire                          clk,
49	    input  wire                          rst,
50	
51	    /*
52	     * Ethernet frame inputs
53	     */
54	    input  wire [S_COUNT-1:0]            s_eth_hdr_valid,
55	    output wire [S_COUNT-1:0]            s_eth_hdr_ready,
56	    input  wire [S_COUNT*48-1:0]         s_eth_dest_mac,
57	    input  wire [S_COUNT*48-1:0]         s_eth_src_mac,
58	    input  wire [S_COUNT*16-1:0]         s_eth_type,
59	    input  wire [S_COUNT*DATA_WIDTH-1:0] s_eth_payload_axis_tdata,
60	    input  wire [S_COUNT*KEEP_WIDTH-1:0] s_eth_payload_axis_tkeep,
61	    input  wire [S_COUNT-1:0]            s_eth_payload_axis_tvalid,
62	    output wire [S_COUNT-1:0]            s_eth_payload_axis_tready,
63	    input  wire [S_COUNT-1:0]            s_eth_payload_axis_tlast,
64	    input  wire [S_COUNT*ID_WIDTH-1:0]   s_eth_payload_axis_tid,
65	    input  wire [S_COUNT*DEST_WIDTH-1:0] s_eth_payload_axis_tdest,
66	    input  wire [S_COUNT*USER_WIDTH-1:0] s_eth_payload_axis_tuser,
67	
68	    /*
69	     * Ethernet frame output
70	     */
71	    output wire                          m_eth_hdr_valid,
72	    input  wire                          m_eth_hdr_ready,
73	    output wire [47:0]                   m_eth_dest_mac,
74	    output wire [47:0]                   m_eth_src_mac,
75	    output wire [15:0]                   m_eth_type,
76	    output wire [DATA_WIDTH-1:0]         m_eth_payload_axis_tdata,
77	    output wire [KEEP_WIDTH-1:0]         m_eth_payload_axis_tkeep,
78	    output wire                          m_eth_payload_axis_tvalid,
79	    input  wire                          m_eth_payload_axis_tready,
80	    output wire                          m_eth_payload_axis_tlast,
81	    output wire [ID_WIDTH-1:0]           m_eth_payload_axis_tid,
82	    output wire [DEST_WIDTH-1:0]         m_eth_payload_axis_tdest,
83	    output wire [USER_WIDTH-1:0]         m_eth_payload_axis_tuser,
84	
85	    /*
86	     * Control
87	     */
88	    input  wire                          enable,
89	    input  wire [$clog2(S_COUNT)-1:0]    select
90	);
91	
92	parameter CL_S_COUNT = $clog2(S_COUNT);
93	
94	reg [CL_S_COUNT-1:0] select_reg = 2'd0, select_next;
95	reg frame_reg = 1'b0, frame_next;
96	
97	reg [S_COUNT-1:0] s_eth_hdr_ready_reg = 0, s_eth_hdr_ready_next;
98	
99	reg [S_COUNT-1:0] s_eth_payload_axis_tready_reg = 0, s_eth_payload_axis_tready_next;
100	
101	reg m_eth_hdr_valid_reg = 1'b0, m_eth_hdr_valid_next;
102	reg [47:0] m_eth_dest_mac_reg = 48'd0, m_eth_dest_mac_next;
103	reg [47:0] m_eth_src_mac_reg = 48'd0, m_eth_src_mac_next;
104	reg [15:0] m_eth_type_reg = 16'd0, m_eth_type_next;
105	
106	// internal datapath
107	reg  [DATA_WIDTH-1:0] m_eth_payload_axis_tdata_int;
108	reg  [KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep_int;
109	reg                   m_eth_payload_axis_tvalid_int;
110	reg                   m_eth_payload_axis_tready_int_reg = 1'b0;
111	reg                   m_eth_payload_axis_tlast_int;
112	reg  [ID_WIDTH-1:0]   m_eth_payload_axis_tid_int;
113	reg  [DEST_WIDTH-1:0] m_eth_payload_axis_tdest_int;
114	reg  [USER_WIDTH-1:0] m_eth_payload_axis_tuser_int;
115	wire                  m_eth_payload_axis_tready_int_early;
116	
117	assign s_eth_hdr_ready = s_eth_hdr_ready_reg;
118	
119	assign s_eth_payload_axis_tready = s_eth_payload_axis_tready_reg;
120	
121	assign m_eth_hdr_valid = m_eth_hdr_valid_reg;
122	assign m_eth_dest_mac = m_eth_dest_mac_reg;
123	assign m_eth_src_mac = m_eth_src_mac_reg;
124	assign m_eth_type = m_eth_type_reg;
125	
126	// mux for incoming packet
127	wire [DATA_WIDTH-1:0] current_s_tdata  = s_eth_payload_axis_tdata[select_reg*DATA_WIDTH +: DATA_WIDTH];
128	wire [KEEP_WIDTH-1:0] current_s_tkeep  = s_eth_payload_axis_tkeep[select_reg*KEEP_WIDTH +: KEEP_WIDTH];
129	wire                  current_s_tvalid = s_eth_payload_axis_tvalid[select_reg];
130	wire                  current_s_tready = s_eth_payload_axis_tready[select_reg];
131	wire                  current_s_tlast  = s_eth_payload_axis_tlast[select_reg];
132	wire [ID_WIDTH-1:0]   current_s_tid    = s_eth_payload_axis_tid[select_reg*ID_WIDTH +: ID_WIDTH];
133	wire [DEST_WIDTH-1:0] current_s_tdest  = s_eth_payload_axis_tdest[select_reg*DEST_WIDTH +: DEST_WIDTH];
134	wire [USER_WIDTH-1:0] current_s_tuser  = s_eth_payload_axis_tuser[select_reg*USER_WIDTH +: USER_WIDTH];
135	
136	always @* begin
137	    select_next = select_reg;
138	    frame_next = frame_reg;
139	
140	    s_eth_hdr_ready_next = 0;
141	
142	    s_eth_payload_axis_tready_next = 0;
143	
144	    m_eth_hdr_valid_next = m_eth_hdr_valid_reg && !m_eth_hdr_ready;
145	    m_eth_dest_mac_next = m_eth_dest_mac_reg;
146	    m_eth_src_mac_next = m_eth_src_mac_reg;
147	    m_eth_type_next = m_eth_type_reg;
148	
149	    if (current_s_tvalid & current_s_tready) begin
150	        // end of frame detection
151	        if (current_s_tlast) begin
152	            frame_next = 1'b0;
153	        end
154	    end
155	
156	    if (!frame_reg && enable && !m_eth_hdr_valid && (s_eth_hdr_valid & (1 << select))) begin
157	        // start of frame, grab select value
158	        frame_next = 1'b1;
159	        select_next = select;
160	
161	        s_eth_hdr_ready_next = (1 << select);
162	
163	        m_eth_hdr_valid_next = 1'b1;
164	        m_eth_dest_mac_next = s_eth_dest_mac[select*48 +: 48];
165	        m_eth_src_mac_next = s_eth_src_mac[select*48 +: 48];
166	        m_eth_type_next = s_eth_type[select*16 +: 16];
167	    end
168	
169	    // generate ready signal on selected port
170	    s_eth_payload_axis_tready_next = (m_eth_payload_axis_tready_int_early && frame_next) << select_next;
171	
172	    // pass through selected packet data
173	    m_eth_payload_axis_tdata_int  = current_s_tdata;
174	    m_eth_payload_axis_tkeep_int  = current_s_tkeep;
175	    m_eth_payload_axis_tvalid_int = current_s_tvalid && current_s_tready && frame_reg;
176	    m_eth_payload_axis_tlast_int  = current_s_tlast;
177	    m_eth_payload_axis_tid_int    = current_s_tid;
178	    m_eth_payload_axis_tdest_int  = current_s_tdest;
179	    m_eth_payload_axis_tuser_int  = current_s_tuser;
180	end
181	
182	always @(posedge clk) begin
183	    if (rst) begin
184	        select_reg <= 0;
185	        frame_reg <= 1'b0;
186	        s_eth_hdr_ready_reg <= 0;
187	        s_eth_payload_axis_tready_reg <= 0;
188	        m_eth_hdr_valid_reg <= 1'b0;
189	    end else begin
190	        select_reg <= select_next;
191	        frame_reg <= frame_next;
192	        s_eth_hdr_ready_reg <= s_eth_hdr_ready_next;
193	        s_eth_payload_axis_tready_reg <= s_eth_payload_axis_tready_next;
194	        m_eth_hdr_valid_reg <= m_eth_hdr_valid_next;
195	    end
196	
197	    m_eth_dest_mac_reg <= m_eth_dest_mac_next;
198	    m_eth_src_mac_reg <= m_eth_src_mac_next;
199	    m_eth_type_reg <= m_eth_type_next;
200	end
201	
202	// output datapath logic
203	reg [DATA_WIDTH-1:0] m_eth_payload_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
204	reg [KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
205	reg                  m_eth_payload_axis_tvalid_reg = 1'b0, m_eth_payload_axis_tvalid_next;
206	reg                  m_eth_payload_axis_tlast_reg  = 1'b0;
207	reg [ID_WIDTH-1:0]   m_eth_payload_axis_tid_reg    = {ID_WIDTH{1'b0}};
208	reg [DEST_WIDTH-1:0] m_eth_payload_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
209	reg [USER_WIDTH-1:0] m_eth_payload_axis_tuser_reg  = {USER_WIDTH{1'b0}};
210	
211	reg [DATA_WIDTH-1:0] temp_m_eth_payload_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
212	reg [KEEP_WIDTH-1:0] temp_m_eth_payload_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
213	reg                  temp_m_eth_payload_axis_tvalid_reg = 1'b0, temp_m_eth_payload_axis_tvalid_next;
214	reg                  temp_m_eth_payload_axis_tlast_reg  = 1'b0;
215	reg [ID_WIDTH-1:0]   temp_m_eth_payload_axis_tid_reg    = {ID_WIDTH{1'b0}};
216	reg [DEST_WIDTH-1:0] temp_m_eth_payload_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
217	reg [USER_WIDTH-1:0] temp_m_eth_payload_axis_tuser_reg  = {USER_WIDTH{1'b0}};
218	
219	// datapath control
220	reg store_axis_int_to_output;
221	reg store_axis_int_to_temp;
222	reg store_axis_temp_to_output;
223	
224	assign m_eth_payload_axis_tdata  = m_eth_payload_axis_tdata_reg;
225	assign m_eth_payload_axis_tkeep  = KEEP_ENABLE ? m_eth_payload_axis_tkeep_reg : {KEEP_WIDTH{1'b1}};
226	assign m_eth_payload_axis_tvalid = m_eth_payload_axis_tvalid_reg;
227	assign m_eth_payload_axis_tlast  = m_eth_payload_axis_tlast_reg;
228	assign m_eth_payload_axis_tid    = ID_ENABLE   ? m_eth_payload_axis_tid_reg   : {ID_WIDTH{1'b0}};
229	assign m_eth_payload_axis_tdest  = DEST_ENABLE ? m_eth_payload_axis_tdest_reg : {DEST_WIDTH{1'b0}};
230	assign m_eth_payload_axis_tuser  = USER_ENABLE ? m_eth_payload_axis_tuser_reg : {USER_WIDTH{1'b0}};
231	
232	// enable ready input next cycle if output is ready or if both output registers are empty
233	assign m_eth_payload_axis_tready_int_early = m_eth_payload_axis_tready || (!temp_m_eth_payload_axis_tvalid_reg && !m_eth_payload_axis_tvalid_reg);
234	
235	always @* begin
236	    // transfer sink ready state to source
237	    m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_reg;
238	    temp_m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
239	
240	    store_axis_int_to_output = 1'b0;
241	    store_axis_int_to_temp = 1'b0;
242	    store_axis_temp_to_output = 1'b0;
243	
244	    if (m_eth_payload_axis_tready_int_reg) begin
245	        // input is ready
246	        if (m_eth_payload_axis_tready || !m_eth_payload_axis_tvalid_reg) begin
247	            // output is ready or currently not valid, transfer data to output
248	            m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
249	            store_axis_int_to_output = 1'b1;
250	        end else begin
251	            // output is not ready, store input in temp
252	            temp_m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
253	            store_axis_int_to_temp = 1'b1;
254	        end
255	    end else if (m_eth_payload_axis_tready) begin
256	        // input is not ready, but output is ready
257	        m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
258	        temp_m_eth_payload_axis_tvalid_next = 1'b0;
259	        store_axis_temp_to_output = 1'b1;
260	    end
261	end
262	
263	always @(posedge clk) begin
264	    m_eth_payload_axis_tvalid_reg <= m_eth_payload_axis_tvalid_next;
265	    m_eth_payload_axis_tready_int_reg <= m_eth_payload_axis_tready_int_early;
266	    temp_m_eth_payload_axis_tvalid_reg <= temp_m_eth_payload_axis_tvalid_next;
267	
268	    // datapath
269	    if (store_axis_int_to_output) begin
270	        m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
271	        m_eth_payload_axis_tkeep_reg <= m_eth_payload_axis_tkeep_int;
272	        m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
273	        m_eth_payload_axis_tid_reg   <= m_eth_payload_axis_tid_int;
274	        m_eth_payload_axis_tdest_reg <= m_eth_payload_axis_tdest_int;
275	        m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
276	    end else if (store_axis_temp_to_output) begin
277	        m_eth_payload_axis_tdata_reg <= temp_m_eth_payload_axis_tdata_reg;
278	        m_eth_payload_axis_tkeep_reg <= temp_m_eth_payload_axis_tkeep_reg;
279	        m_eth_payload_axis_tlast_reg <= temp_m_eth_payload_axis_tlast_reg;
280	        m_eth_payload_axis_tid_reg   <= temp_m_eth_payload_axis_tid_reg;
281	        m_eth_payload_axis_tdest_reg <= temp_m_eth_payload_axis_tdest_reg;
282	        m_eth_payload_axis_tuser_reg <= temp_m_eth_payload_axis_tuser_reg;
283	    end
284	
285	    if (store_axis_int_to_temp) begin
286	        temp_m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
287	        temp_m_eth_payload_axis_tkeep_reg <= m_eth_payload_axis_tkeep_int;
288	        temp_m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
289	        temp_m_eth_payload_axis_tid_reg   <= m_eth_payload_axis_tid_int;
290	        temp_m_eth_payload_axis_tdest_reg <= m_eth_payload_axis_tdest_int;
291	        temp_m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
292	    end
293	
294	    if (rst) begin
295	        m_eth_payload_axis_tvalid_reg <= 1'b0;
296	        m_eth_payload_axis_tready_int_reg <= 1'b0;
297	        temp_m_eth_payload_axis_tvalid_reg <= 1'b0;
298	    end
299	end
300	
301	endmodule
302	
303	`resetall
304

