25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * Ethernet demultiplexer
33	 */
34	module eth_demux #
35	(
36	    parameter M_COUNT = 4,
37	    parameter DATA_WIDTH = 8,
38	    parameter KEEP_ENABLE = (DATA_WIDTH>8),
39	    parameter KEEP_WIDTH = (DATA_WIDTH/8),
40	    parameter ID_ENABLE = 0,
41	    parameter ID_WIDTH = 8,
42	    parameter DEST_ENABLE = 0,
43	    parameter DEST_WIDTH = 8,
44	    parameter USER_ENABLE = 1,
45	    parameter USER_WIDTH = 1
46	)
47	(
48	    input  wire                          clk,
49	    input  wire                          rst,
50	
51	    /*
52	     * Ethernet frame input
53	     */
54	    input  wire                          s_eth_hdr_valid,
55	    output wire                          s_eth_hdr_ready,
56	    input  wire [47:0]                   s_eth_dest_mac,
57	    input  wire [47:0]                   s_eth_src_mac,
58	    input  wire [15:0]                   s_eth_type,
59	    input  wire [DATA_WIDTH-1:0]         s_eth_payload_axis_tdata,
60	    input  wire [KEEP_WIDTH-1:0]         s_eth_payload_axis_tkeep,
61	    input  wire                          s_eth_payload_axis_tvalid,
62	    output wire                          s_eth_payload_axis_tready,
63	    input  wire                          s_eth_payload_axis_tlast,
64	    input  wire [ID_WIDTH-1:0]           s_eth_payload_axis_tid,
65	    input  wire [DEST_WIDTH-1:0]         s_eth_payload_axis_tdest,
66	    input  wire [USER_WIDTH-1:0]         s_eth_payload_axis_tuser,
67	
68	    /*
69	     * Ethernet frame outputs
70	     */
71	    output wire [M_COUNT-1:0]            m_eth_hdr_valid,
72	    input  wire [M_COUNT-1:0]            m_eth_hdr_ready,
73	    output wire [M_COUNT*48-1:0]         m_eth_dest_mac,
74	    output wire [M_COUNT*48-1:0]         m_eth_src_mac,
75	    output wire [M_COUNT*16-1:0]         m_eth_type,
76	    output wire [M_COUNT*DATA_WIDTH-1:0] m_eth_payload_axis_tdata,
77	    output wire [M_COUNT*KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep,
78	    output wire [M_COUNT-1:0]            m_eth_payload_axis_tvalid,
79	    input  wire [M_COUNT-1:0]            m_eth_payload_axis_tready,
80	    output wire [M_COUNT-1:0]            m_eth_payload_axis_tlast,
81	    output wire [M_COUNT*ID_WIDTH-1:0]   m_eth_payload_axis_tid,
82	    output wire [M_COUNT*DEST_WIDTH-1:0] m_eth_payload_axis_tdest,
83	    output wire [M_COUNT*USER_WIDTH-1:0] m_eth_payload_axis_tuser,
84	
85	    /*
86	     * Control
87	     */
88	    input  wire                          enable,
89	    input  wire                          drop,
90	    input  wire [$clog2(M_COUNT)-1:0]    select
91	);
92	
93	parameter CL_M_COUNT = $clog2(M_COUNT);
94	
95	reg [CL_M_COUNT-1:0] select_reg = {CL_M_COUNT{1'b0}}, select_ctl, select_next;
96	reg drop_reg = 1'b0, drop_ctl, drop_next;
97	reg frame_reg = 1'b0, frame_ctl, frame_next;
98	
99	reg s_eth_hdr_ready_reg = 1'b0, s_eth_hdr_ready_next;
100	
101	reg s_eth_payload_axis_tready_reg = 1'b0, s_eth_payload_axis_tready_next;
102	
103	reg [M_COUNT-1:0] m_eth_hdr_valid_reg = 0, m_eth_hdr_valid_next;
104	reg [47:0] m_eth_dest_mac_reg = 48'd0, m_eth_dest_mac_next;
105	reg [47:0] m_eth_src_mac_reg = 48'd0, m_eth_src_mac_next;
106	reg [15:0] m_eth_type_reg = 16'd0, m_eth_type_next;
107	
108	// internal datapath
109	reg  [DATA_WIDTH-1:0] m_eth_payload_axis_tdata_int;
110	reg  [KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep_int;
111	reg  [M_COUNT-1:0]    m_eth_payload_axis_tvalid_int;
112	reg                   m_eth_payload_axis_tready_int_reg = 1'b0;
113	reg                   m_eth_payload_axis_tlast_int;
114	reg  [ID_WIDTH-1:0]   m_eth_payload_axis_tid_int;
115	reg  [DEST_WIDTH-1:0] m_eth_payload_axis_tdest_int;
116	reg  [USER_WIDTH-1:0] m_eth_payload_axis_tuser_int;
117	wire                  m_eth_payload_axis_tready_int_early;
118	
119	assign s_eth_hdr_ready = s_eth_hdr_ready_reg && enable;
120	
121	assign s_eth_payload_axis_tready = s_eth_payload_axis_tready_reg && enable;
122	
123	assign m_eth_hdr_valid = m_eth_hdr_valid_reg;
124	assign m_eth_dest_mac = {M_COUNT{m_eth_dest_mac_reg}};
125	assign m_eth_src_mac = {M_COUNT{m_eth_src_mac_reg}};
126	assign m_eth_type = {M_COUNT{m_eth_type_reg}};
127	
128	integer i;
129	
130	always @* begin
131	    select_next = select_reg;
132	    select_ctl = select_reg;
133	    drop_next = drop_reg;
134	    drop_ctl = drop_reg;
135	    frame_next = frame_reg;
136	    frame_ctl = frame_reg;
137	
138	    s_eth_hdr_ready_next = 1'b0;
139	
140	    s_eth_payload_axis_tready_next = 1'b0;
141	
142	    m_eth_hdr_valid_next = m_eth_hdr_valid_reg & ~m_eth_hdr_ready;
143	    m_eth_dest_mac_next = m_eth_dest_mac_reg;
144	    m_eth_src_mac_next = m_eth_src_mac_reg;
145	    m_eth_type_next = m_eth_type_reg;
146	
147	    if (s_eth_payload_axis_tvalid && s_eth_payload_axis_tready) begin
148	        // end of frame detection
149	        if (s_eth_payload_axis_tlast) begin
150	            frame_next = 1'b0;
151	            drop_next = 1'b0;
152	        end
153	    end
154	
155	    if (!frame_reg && s_eth_hdr_valid && s_eth_hdr_ready) begin
156	        // start of frame, grab select value
157	        select_ctl = select;
158	        drop_ctl = drop;
159	        frame_ctl = 1'b1;
160	
161	        select_next = select_ctl;
162	        drop_next = drop_ctl;
163	        frame_next = frame_ctl;
164	
165	        s_eth_hdr_ready_next = 1'b0;
166	
167	        m_eth_hdr_valid_next = (!drop_ctl) << select_ctl;
168	        m_eth_dest_mac_next = s_eth_dest_mac;
169	        m_eth_src_mac_next = s_eth_src_mac;
170	        m_eth_type_next = s_eth_type;
171	    end
172	
173	    s_eth_hdr_ready_next = !frame_next && !m_eth_hdr_valid_next;
174	
175	    s_eth_payload_axis_tready_next = (m_eth_payload_axis_tready_int_early || drop_ctl) && frame_ctl;
176	
177	    m_eth_payload_axis_tdata_int  = s_eth_payload_axis_tdata;
178	    m_eth_payload_axis_tkeep_int  = s_eth_payload_axis_tkeep;
179	    m_eth_payload_axis_tvalid_int = (s_eth_payload_axis_tvalid && s_eth_payload_axis_tready && !drop_ctl) << select_ctl;
180	    m_eth_payload_axis_tlast_int  = s_eth_payload_axis_tlast;
181	    m_eth_payload_axis_tid_int    = s_eth_payload_axis_tid;
182	    m_eth_payload_axis_tdest_int  = s_eth_payload_axis_tdest;
183	    m_eth_payload_axis_tuser_int  = s_eth_payload_axis_tuser; 
184	end
185	
186	always @(posedge clk) begin
187	    if (rst) begin
188	        select_reg <= 2'd0;
189	        drop_reg <= 1'b0;
190	        frame_reg <= 1'b0;
191	        s_eth_hdr_ready_reg <= 1'b0;
192	        s_eth_payload_axis_tready_reg <= 1'b0;
193	        m_eth_hdr_valid_reg <= 0;
194	    end else begin
195	        select_reg <= select_next;
196	        drop_reg <= drop_next;
197	        frame_reg <= frame_next;
198	        s_eth_hdr_ready_reg <= s_eth_hdr_ready_next;
199	        s_eth_payload_axis_tready_reg <= s_eth_payload_axis_tready_next;
200	        m_eth_hdr_valid_reg <= m_eth_hdr_valid_next;
201	    end
202	
203	    m_eth_dest_mac_reg <= m_eth_dest_mac_next;
204	    m_eth_src_mac_reg <= m_eth_src_mac_next;
205	    m_eth_type_reg <= m_eth_type_next;
206	end
207	
208	// output datapath logic
209	reg [DATA_WIDTH-1:0] m_eth_payload_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
210	reg [KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
211	reg [M_COUNT-1:0]    m_eth_payload_axis_tvalid_reg = {M_COUNT{1'b0}}, m_eth_payload_axis_tvalid_next;
212	reg                  m_eth_payload_axis_tlast_reg  = 1'b0;
213	reg [ID_WIDTH-1:0]   m_eth_payload_axis_tid_reg    = {ID_WIDTH{1'b0}};
214	reg [DEST_WIDTH-1:0] m_eth_payload_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
215	reg [USER_WIDTH-1:0] m_eth_payload_axis_tuser_reg  = {USER_WIDTH{1'b0}};
216	
217	reg [DATA_WIDTH-1:0] temp_m_eth_payload_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
218	reg [KEEP_WIDTH-1:0] temp_m_eth_payload_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
219	reg [M_COUNT-1:0]    temp_m_eth_payload_axis_tvalid_reg = {M_COUNT{1'b0}}, temp_m_eth_payload_axis_tvalid_next;
220	reg                  temp_m_eth_payload_axis_tlast_reg  = 1'b0;
221	reg [ID_WIDTH-1:0]   temp_m_eth_payload_axis_tid_reg    = {ID_WIDTH{1'b0}};
222	reg [DEST_WIDTH-1:0] temp_m_eth_payload_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
223	reg [USER_WIDTH-1:0] temp_m_eth_payload_axis_tuser_reg  = {USER_WIDTH{1'b0}};
224	
225	// datapath control
226	reg store_axis_int_to_output;
227	reg store_axis_int_to_temp;
228	reg store_eth_payload_axis_temp_to_output;
229	
230	assign m_eth_payload_axis_tdata  = {M_COUNT{m_eth_payload_axis_tdata_reg}};
231	assign m_eth_payload_axis_tkeep  = KEEP_ENABLE ? {M_COUNT{m_eth_payload_axis_tkeep_reg}} : {M_COUNT*KEEP_WIDTH{1'b1}};
232	assign m_eth_payload_axis_tvalid = m_eth_payload_axis_tvalid_reg;
233	assign m_eth_payload_axis_tlast  = {M_COUNT{m_eth_payload_axis_tlast_reg}};
234	assign m_eth_payload_axis_tid    = ID_ENABLE   ? {M_COUNT{m_eth_payload_axis_tid_reg}}   : {M_COUNT*ID_WIDTH{1'b0}};
235	assign m_eth_payload_axis_tdest  = DEST_ENABLE ? {M_COUNT{m_eth_payload_axis_tdest_reg}} : {M_COUNT*DEST_WIDTH{1'b0}};
236	assign m_eth_payload_axis_tuser  = USER_ENABLE ? {M_COUNT{m_eth_payload_axis_tuser_reg}} : {M_COUNT*USER_WIDTH{1'b0}};
237	
238	// enable ready input next cycle if output is ready or if both output registers are empty
239	assign m_eth_payload_axis_tready_int_early = (m_eth_payload_axis_tready & m_eth_payload_axis_tvalid) || (!temp_m_eth_payload_axis_tvalid_reg && !m_eth_payload_axis_tvalid_reg);
240	
241	always @* begin
242	    // transfer sink ready state to source
243	    m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_reg;
244	    temp_m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
245	
246	    store_axis_int_to_output = 1'b0;
247	    store_axis_int_to_temp = 1'b0;
248	    store_eth_payload_axis_temp_to_output = 1'b0;
249	
250	    if (m_eth_payload_axis_tready_int_reg) begin
251	        // input is ready
252	        if ((m_eth_payload_axis_tready & m_eth_payload_axis_tvalid) || !m_eth_payload_axis_tvalid) begin
253	            // output is ready or currently not valid, transfer data to output
254	            m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
255	            store_axis_int_to_output = 1'b1;
256	        end else begin
257	            // output is not ready, store input in temp
258	            temp_m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
259	            store_axis_int_to_temp = 1'b1;
260	        end
261	    end else if (m_eth_payload_axis_tready & m_eth_payload_axis_tvalid) begin
262	        // input is not ready, but output is ready
263	        m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
264	        temp_m_eth_payload_axis_tvalid_next = 1'b0;
265	        store_eth_payload_axis_temp_to_output = 1'b1;
266	    end
267	end
268	
269	always @(posedge clk) begin
270	    m_eth_payload_axis_tvalid_reg <= m_eth_payload_axis_tvalid_next;
271	    m_eth_payload_axis_tready_int_reg <= m_eth_payload_axis_tready_int_early;
272	    temp_m_eth_payload_axis_tvalid_reg <= temp_m_eth_payload_axis_tvalid_next;
273	
274	    // datapath
275	    if (store_axis_int_to_output) begin
276	        m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
277	        m_eth_payload_axis_tkeep_reg <= m_eth_payload_axis_tkeep_int;
278	        m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
279	        m_eth_payload_axis_tid_reg   <= m_eth_payload_axis_tid_int;
280	        m_eth_payload_axis_tdest_reg <= m_eth_payload_axis_tdest_int;
281	        m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
282	    end else if (store_eth_payload_axis_temp_to_output) begin
283	        m_eth_payload_axis_tdata_reg <= temp_m_eth_payload_axis_tdata_reg;
284	        m_eth_payload_axis_tkeep_reg <= temp_m_eth_payload_axis_tkeep_reg;
285	        m_eth_payload_axis_tlast_reg <= temp_m_eth_payload_axis_tlast_reg;
286	        m_eth_payload_axis_tid_reg   <= temp_m_eth_payload_axis_tid_reg;
287	        m_eth_payload_axis_tdest_reg <= temp_m_eth_payload_axis_tdest_reg;
288	        m_eth_payload_axis_tuser_reg <= temp_m_eth_payload_axis_tuser_reg;
289	    end
290	
291	    if (store_axis_int_to_temp) begin
292	        temp_m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
293	        temp_m_eth_payload_axis_tkeep_reg <= m_eth_payload_axis_tkeep_int;
294	        temp_m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
295	        temp_m_eth_payload_axis_tid_reg   <= m_eth_payload_axis_tid_int;
296	        temp_m_eth_payload_axis_tdest_reg <= m_eth_payload_axis_tdest_int;
297	        temp_m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
298	    end
299	
300	    if (rst) begin
301	        m_eth_payload_axis_tvalid_reg <= {M_COUNT{1'b0}};
302	        m_eth_payload_axis_tready_int_reg <= 1'b0;
303	        temp_m_eth_payload_axis_tvalid_reg <= 1'b0;
304	    end
305	end
306	
307	endmodule
308	
309	`resetall
