30	
31	/*
32	 * Ethernet arbitrated multiplexer
33	 */
34	module eth_arb_mux #
35	(
36	    parameter S_COUNT = 4,
37	    parameter DATA_WIDTH = 8,
38	    parameter KEEP_ENABLE = (DATA_WIDTH>8),
39	    parameter KEEP_WIDTH = (DATA_WIDTH/8),
40	    parameter ID_ENABLE = 0,
41	    parameter ID_WIDTH = 8,
42	    parameter DEST_ENABLE = 0,
43	    parameter DEST_WIDTH = 8,
44	    parameter USER_ENABLE = 1,
45	    parameter USER_WIDTH = 1,
46	    // select round robin arbitration
47	    parameter ARB_TYPE_ROUND_ROBIN = 0,
48	    // LSB priority selection
49	    parameter ARB_LSB_HIGH_PRIORITY = 1
50	)
51	(
52	    input  wire                          clk,
53	    input  wire                          rst,
54	
55	    /*
56	     * Ethernet frame inputs
57	     */
58	    input  wire [S_COUNT-1:0]            s_eth_hdr_valid,
59	    output wire [S_COUNT-1:0]            s_eth_hdr_ready,
60	    input  wire [S_COUNT*48-1:0]         s_eth_dest_mac,
61	    input  wire [S_COUNT*48-1:0]         s_eth_src_mac,
62	    input  wire [S_COUNT*16-1:0]         s_eth_type,
63	    input  wire [S_COUNT*DATA_WIDTH-1:0] s_eth_payload_axis_tdata,
64	    input  wire [S_COUNT*KEEP_WIDTH-1:0] s_eth_payload_axis_tkeep,
65	    input  wire [S_COUNT-1:0]            s_eth_payload_axis_tvalid,
66	    output wire [S_COUNT-1:0]            s_eth_payload_axis_tready,
67	    input  wire [S_COUNT-1:0]            s_eth_payload_axis_tlast,
68	    input  wire [S_COUNT*ID_WIDTH-1:0]   s_eth_payload_axis_tid,
69	    input  wire [S_COUNT*DEST_WIDTH-1:0] s_eth_payload_axis_tdest,
70	    input  wire [S_COUNT*USER_WIDTH-1:0] s_eth_payload_axis_tuser,
71	
72	    /*
73	     * Ethernet frame output
74	     */
75	    output wire                          m_eth_hdr_valid,
76	    input  wire                          m_eth_hdr_ready,
77	    output wire [47:0]                   m_eth_dest_mac,
78	    output wire [47:0]                   m_eth_src_mac,
79	    output wire [15:0]                   m_eth_type,
80	    output wire [DATA_WIDTH-1:0]         m_eth_payload_axis_tdata,
81	    output wire [KEEP_WIDTH-1:0]         m_eth_payload_axis_tkeep,
82	    output wire                          m_eth_payload_axis_tvalid,
83	    input  wire                          m_eth_payload_axis_tready,
84	    output wire                          m_eth_payload_axis_tlast,
85	    output wire [ID_WIDTH-1:0]           m_eth_payload_axis_tid,
86	    output wire [DEST_WIDTH-1:0]         m_eth_payload_axis_tdest,
87	    output wire [USER_WIDTH-1:0]         m_eth_payload_axis_tuser
88	);
89	
90	parameter CL_S_COUNT = $clog2(S_COUNT);
91	
92	reg frame_reg = 1'b0, frame_next;
93	
94	reg [S_COUNT-1:0] s_eth_hdr_ready_reg = {S_COUNT{1'b0}}, s_eth_hdr_ready_next;
95	
96	reg m_eth_hdr_valid_reg = 1'b0, m_eth_hdr_valid_next;
97	reg [47:0] m_eth_dest_mac_reg = 48'd0, m_eth_dest_mac_next;
98	reg [47:0] m_eth_src_mac_reg = 48'd0, m_eth_src_mac_next;
99	reg [15:0] m_eth_type_reg = 16'd0, m_eth_type_next;
100	
101	wire [S_COUNT-1:0] request;
102	wire [S_COUNT-1:0] acknowledge;
103	wire [S_COUNT-1:0] grant;
104	wire grant_valid;
105	wire [CL_S_COUNT-1:0] grant_encoded;
106	
107	// internal datapath
108	reg  [DATA_WIDTH-1:0] m_eth_payload_axis_tdata_int;
109	reg  [KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep_int;
110	reg                   m_eth_payload_axis_tvalid_int;
111	reg                   m_eth_payload_axis_tready_int_reg = 1'b0;
112	reg                   m_eth_payload_axis_tlast_int;
113	reg  [ID_WIDTH-1:0]   m_eth_payload_axis_tid_int;
114	reg  [DEST_WIDTH-1:0] m_eth_payload_axis_tdest_int;
115	reg  [USER_WIDTH-1:0] m_eth_payload_axis_tuser_int;
116	wire                  m_eth_payload_axis_tready_int_early;
117	
118	assign s_eth_hdr_ready = s_eth_hdr_ready_reg;
119	
120	assign s_eth_payload_axis_tready = (m_eth_payload_axis_tready_int_reg && grant_valid) << grant_encoded;
121	
122	assign m_eth_hdr_valid = m_eth_hdr_valid_reg;
123	assign m_eth_dest_mac = m_eth_dest_mac_reg;
124	assign m_eth_src_mac = m_eth_src_mac_reg;
125	assign m_eth_type = m_eth_type_reg;
126	
127	// mux for incoming packet
128	wire [DATA_WIDTH-1:0] current_s_tdata  = s_eth_payload_axis_tdata[grant_encoded*DATA_WIDTH +: DATA_WIDTH];
129	wire [KEEP_WIDTH-1:0] current_s_tkeep  = s_eth_payload_axis_tkeep[grant_encoded*KEEP_WIDTH +: KEEP_WIDTH];
130	wire                  current_s_tvalid = s_eth_payload_axis_tvalid[grant_encoded];
131	wire                  current_s_tready = s_eth_payload_axis_tready[grant_encoded];
132	wire                  current_s_tlast  = s_eth_payload_axis_tlast[grant_encoded];
133	wire [ID_WIDTH-1:0]   current_s_tid    = s_eth_payload_axis_tid[grant_encoded*ID_WIDTH +: ID_WIDTH];
134	wire [DEST_WIDTH-1:0] current_s_tdest  = s_eth_payload_axis_tdest[grant_encoded*DEST_WIDTH +: DEST_WIDTH];
135	wire [USER_WIDTH-1:0] current_s_tuser  = s_eth_payload_axis_tuser[grant_encoded*USER_WIDTH +: USER_WIDTH];
136	
137	// arbiter instance
138	arbiter #(
139	    .PORTS(S_COUNT),
140	    .ARB_TYPE_ROUND_ROBIN(ARB_TYPE_ROUND_ROBIN),
141	    .ARB_BLOCK(1),
142	    .ARB_BLOCK_ACK(1),
143	    .ARB_LSB_HIGH_PRIORITY(ARB_LSB_HIGH_PRIORITY)
144	)
145	arb_inst (
146	    .clk(clk),
147	    .rst(rst),
148	    .request(request),
149	    .acknowledge(acknowledge),
150	    .grant(grant),
151	    .grant_valid(grant_valid),
152	    .grant_encoded(grant_encoded)
153	);
154	
155	assign request = s_eth_hdr_valid & ~grant;
156	assign acknowledge = grant & s_eth_payload_axis_tvalid & s_eth_payload_axis_tready & s_eth_payload_axis_tlast;
157	
158	always @* begin
159	    frame_next = frame_reg;
160	
161	    s_eth_hdr_ready_next = {S_COUNT{1'b0}};
162	
163	    m_eth_hdr_valid_next = m_eth_hdr_valid_reg && !m_eth_hdr_ready;
164	    m_eth_dest_mac_next = m_eth_dest_mac_reg;
165	    m_eth_src_mac_next = m_eth_src_mac_reg;
166	    m_eth_type_next = m_eth_type_reg;
167	
168	    if (s_eth_payload_axis_tvalid[grant_encoded] && s_eth_payload_axis_tready[grant_encoded]) begin
169	        // end of frame detection
170	        if (s_eth_payload_axis_tlast[grant_encoded]) begin
171	            frame_next = 1'b0;
172	        end
173	    end
174	
175	    if (!frame_reg && grant_valid && (m_eth_hdr_ready || !m_eth_hdr_valid)) begin
176	        // start of frame
177	        frame_next = 1'b1;
178	
179	        s_eth_hdr_ready_next = grant;
180	
181	        m_eth_hdr_valid_next = 1'b1;
182	        m_eth_dest_mac_next = s_eth_dest_mac[grant_encoded*48 +: 48];
183	        m_eth_src_mac_next = s_eth_src_mac[grant_encoded*48 +: 48];
184	        m_eth_type_next = s_eth_type[grant_encoded*16 +: 16];
185	    end
186	
187	    // pass through selected packet data
188	    m_eth_payload_axis_tdata_int  = current_s_tdata;
189	    m_eth_payload_axis_tkeep_int  = current_s_tkeep;
190	    m_eth_payload_axis_tvalid_int = current_s_tvalid && m_eth_payload_axis_tready_int_reg && grant_valid;
191	    m_eth_payload_axis_tlast_int  = current_s_tlast;
192	    m_eth_payload_axis_tid_int    = current_s_tid;
193	    m_eth_payload_axis_tdest_int  = current_s_tdest;
194	    m_eth_payload_axis_tuser_int  = current_s_tuser;
195	end
196	
197	always @(posedge clk) begin
198	    frame_reg <= frame_next;
199	
200	    s_eth_hdr_ready_reg <= s_eth_hdr_ready_next;
201	
202	    m_eth_hdr_valid_reg <= m_eth_hdr_valid_next;
203	    m_eth_dest_mac_reg <= m_eth_dest_mac_next;
204	    m_eth_src_mac_reg <= m_eth_src_mac_next;
205	    m_eth_type_reg <= m_eth_type_next;
206	
207	    if (rst) begin
208	        frame_reg <= 1'b0;
209	        s_eth_hdr_ready_reg <= {S_COUNT{1'b0}};
210	        m_eth_hdr_valid_reg <= 1'b0;
211	    end
212	end
213	
214	// output datapath logic
215	reg [DATA_WIDTH-1:0] m_eth_payload_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
216	reg [KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
217	reg                  m_eth_payload_axis_tvalid_reg = 1'b0, m_eth_payload_axis_tvalid_next;
218	reg                  m_eth_payload_axis_tlast_reg  = 1'b0;
219	reg [ID_WIDTH-1:0]   m_eth_payload_axis_tid_reg    = {ID_WIDTH{1'b0}};
220	reg [DEST_WIDTH-1:0] m_eth_payload_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
221	reg [USER_WIDTH-1:0] m_eth_payload_axis_tuser_reg  = {USER_WIDTH{1'b0}};
222	
223	reg [DATA_WIDTH-1:0] temp_m_eth_payload_axis_tdata_reg  = {DATA_WIDTH{1'b0}};
224	reg [KEEP_WIDTH-1:0] temp_m_eth_payload_axis_tkeep_reg  = {KEEP_WIDTH{1'b0}};
225	reg                  temp_m_eth_payload_axis_tvalid_reg = 1'b0, temp_m_eth_payload_axis_tvalid_next;
226	reg                  temp_m_eth_payload_axis_tlast_reg  = 1'b0;
227	reg [ID_WIDTH-1:0]   temp_m_eth_payload_axis_tid_reg    = {ID_WIDTH{1'b0}};
228	reg [DEST_WIDTH-1:0] temp_m_eth_payload_axis_tdest_reg  = {DEST_WIDTH{1'b0}};
229	reg [USER_WIDTH-1:0] temp_m_eth_payload_axis_tuser_reg  = {USER_WIDTH{1'b0}};
230	
231	// datapath control
232	reg store_axis_int_to_output;
233	reg store_axis_int_to_temp;
234	reg store_eth_payload_axis_temp_to_output;
235	
236	assign m_eth_payload_axis_tdata  = m_eth_payload_axis_tdata_reg;
237	assign m_eth_payload_axis_tkeep  = KEEP_ENABLE ? m_eth_payload_axis_tkeep_reg : {KEEP_WIDTH{1'b1}};
238	assign m_eth_payload_axis_tvalid = m_eth_payload_axis_tvalid_reg;
239	assign m_eth_payload_axis_tlast  = m_eth_payload_axis_tlast_reg;
240	assign m_eth_payload_axis_tid    = ID_ENABLE   ? m_eth_payload_axis_tid_reg   : {ID_WIDTH{1'b0}};
241	assign m_eth_payload_axis_tdest  = DEST_ENABLE ? m_eth_payload_axis_tdest_reg : {DEST_WIDTH{1'b0}};
242	assign m_eth_payload_axis_tuser  = USER_ENABLE ? m_eth_payload_axis_tuser_reg : {USER_WIDTH{1'b0}};
243	
244	// enable ready input next cycle if output is ready or if both output registers are empty
245	assign m_eth_payload_axis_tready_int_early = m_eth_payload_axis_tready || (!temp_m_eth_payload_axis_tvalid_reg && !m_eth_payload_axis_tvalid_reg);
246	
247	always @* begin
248	    // transfer sink ready state to source
249	    m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_reg;
250	    temp_m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
251	
252	    store_axis_int_to_output = 1'b0;
253	    store_axis_int_to_temp = 1'b0;
254	    store_eth_payload_axis_temp_to_output = 1'b0;
255	
256	    if (m_eth_payload_axis_tready_int_reg) begin
257	        // input is ready
258	        if (m_eth_payload_axis_tready || !m_eth_payload_axis_tvalid_reg) begin
259	            // output is ready or currently not valid, transfer data to output
260	            m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
261	            store_axis_int_to_output = 1'b1;
262	        end else begin
263	            // output is not ready, store input in temp
264	            temp_m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
265	            store_axis_int_to_temp = 1'b1;
266	        end
267	    end else if (m_eth_payload_axis_tready) begin
268	        // input is not ready, but output is ready
269	        m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
270	        temp_m_eth_payload_axis_tvalid_next = 1'b0;
271	        store_eth_payload_axis_temp_to_output = 1'b1;
272	    end
273	end
274	
275	always @(posedge clk) begin
276	    m_eth_payload_axis_tvalid_reg <= m_eth_payload_axis_tvalid_next;
277	    m_eth_payload_axis_tready_int_reg <= m_eth_payload_axis_tready_int_early;
278	    temp_m_eth_payload_axis_tvalid_reg <= temp_m_eth_payload_axis_tvalid_next;
279	
280	    // datapath
281	    if (store_axis_int_to_output) begin
282	        m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
283	        m_eth_payload_axis_tkeep_reg <= m_eth_payload_axis_tkeep_int;
284	        m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
285	        m_eth_payload_axis_tid_reg   <= m_eth_payload_axis_tid_int;
286	        m_eth_payload_axis_tdest_reg <= m_eth_payload_axis_tdest_int;
287	        m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
288	    end else if (store_eth_payload_axis_temp_to_output) begin
289	        m_eth_payload_axis_tdata_reg <= temp_m_eth_payload_axis_tdata_reg;
290	        m_eth_payload_axis_tkeep_reg <= temp_m_eth_payload_axis_tkeep_reg;
291	        m_eth_payload_axis_tlast_reg <= temp_m_eth_payload_axis_tlast_reg;
292	        m_eth_payload_axis_tid_reg   <= temp_m_eth_payload_axis_tid_reg;
293	        m_eth_payload_axis_tdest_reg <= temp_m_eth_payload_axis_tdest_reg;
294	        m_eth_payload_axis_tuser_reg <= temp_m_eth_payload_axis_tuser_reg;
295	    end
296	
297	    if (store_axis_int_to_temp) begin
298	        temp_m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
299	        temp_m_eth_payload_axis_tkeep_reg <= m_eth_payload_axis_tkeep_int;
300	        temp_m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
301	        temp_m_eth_payload_axis_tid_reg   <= m_eth_payload_axis_tid_int;
302	        temp_m_eth_payload_axis_tdest_reg <= m_eth_payload_axis_tdest_int;
303	        temp_m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
304	    end
305	
306	    if (rst) begin
307	        m_eth_payload_axis_tvalid_reg <= 1'b0;
308	        m_eth_payload_axis_tready_int_reg <= 1'b0;
309	        temp_m_eth_payload_axis_tvalid_reg <= 1'b0;
310	    end
311	end
312	
313	endmodule
314	
315	`resetall
316

